import {ANIMALS,FARM_POINTS,dailyStatus,careAnimal,farmSupply,setHousing,animalPoint} from './farm.mjs';
import {exchangeInventory} from './progression.mjs';
export function createFarmPanels({getState,capture,isNear,show,changed}){
 const $=id=>document.getElementById(id);
 const statusLine=(label,done)=>'<div class="care-line"><span>'+label+'</span><b class="'+(done?'care-done':'')+'">'+(done?'✓ Heute erledigt':'Noch offen')+'</b></div>';
 const message=m=>m?'<p class="panel-message" role="status">'+m+'</p>':'';
 function animal(id,m=''){
  capture();const s=getState(),def=ANIMALS[id],a=s.farm.animals[id],status=dailyStatus(s,id),near=isNear(id),ready=status.fed&&status.watered&&status.cared;let busy=false;
  show('<span class="eyebrow">DEINE TIERE · TAG '+s.day+'</span><h2>'+def.name+'</h2>'+message(m)+'<p>'+(def.kind==='cow'?'Eine deiner beiden Alpkühe.':def.kind==='goats'?'Zwei neugierige Alpgeissen bei der Scheune.':def.kind==='hens'?'Drei neugierige Hühner mit frischen Nestern.':'Dein Alppferd. Pflege und Parcours bleiben unabhängig voneinander nutzbar.')+'</p><p><b>'+(s.alpLife.housed[id]?(id==='hens'?'Im Hühnerhaus':'In der Scheune'):'Draussen auf der Weide')+'</b></p><div class="care-status">'+statusLine('Frisches Futter',status.fed)+statusLine('Frisches Wasser',status.watered)+statusLine('Pflege & Zuwendung',status.cared)+'</div><div class="compact-work-status"><label>Tagesversorgung <b>'+([status.fed,status.watered,status.cared].filter(Boolean).length)+' / 3</b><progress max="3" value="'+([status.fed,status.watered,status.cared].filter(Boolean).length)+'" aria-label="Tagesversorgung"></progress></label>'+(def.product?'<label>'+(def.kind==='hens'?'Eier sammeln':'Melken')+' <b>'+(status.collected?'✓ Erledigt':ready?'Bereit':'Zuerst versorgen')+'</b><progress max="1" value="'+(status.collected?1:0)+'" aria-label="Erzeugnisse abgeholt"></progress></label>':'')+'</div><p>Vertrauen: '+a.trust+' / 100</p><div class="actions"><button data-care="feed" '+(!near||status.fed?'disabled':'')+'>Füttern · 1 '+def.foodName+'</button><button data-care="water" '+(!near||status.watered?'disabled':'')+'>Wasser geben · Eimer + 1 Wasser</button><button data-care="care" '+(!near||status.cared?'disabled':'')+'>Pflegen · 2 Energie</button>'+(def.product?'<button data-care="collect" class="primary" '+(!near||!ready||status.collected?'disabled':'')+'>'+(status.collected?'Heute abgeholt':def.kind==='hens'?'3 Eier sammeln':def.kind==='goats'?'1 Geissenmilch melken':'2 Milch melken')+'</button>':'')+'</div><div id="farm-work-area" aria-live="polite"></div><button id="animal-housing">'+(s.alpLife.housed[id]?'Auf die Weide lassen':id==='hens'?'Ins Hühnerhaus bringen':'In die Scheune bringen')+'</button><p>'+(near?'Heu mähst du auf der Heuwiese und lagerst es im Heuunterstand. Wasser gibt es am Alpbrunnen.':'Gehe zum Tier auf der Alp, um es zu versorgen.')+'</p><small>Eine vollständige Versorgung und Erzeugnisse sind pro Spieltag möglich. Die nächste Runde beginnt nach einer Nacht in der Hütte. Während du das Spiel geschlossen hast, verschlechtern sich die Tierzustände nicht.</small><button id="farm-overview">Zur Tierübersicht</button>');
  for(const el of document.querySelectorAll('[data-care]'))el.onclick=()=>{if(busy)return;capture();if(!isNear(id)){animal(id,'Gehe zuerst zum Tier.');return;}const commit=()=>{capture();if(getState()!==s||!isNear(id)){animal(id,'Aktion abgebrochen. Gehe zum Tier.');return;}const result=careAnimal(s,id,el.dataset.care,exchangeInventory);if(result.ok)changed();animal(id,result.message);};if(el.dataset.care==='collect'&&def.kind!=='hens'){busy=true;let count=0,done=false;const host=$('farm-work-area');host.innerHTML='<div class="compact-work-status"><label>Melken <b id="milk-percent">0 / 6 · 0 %</b><progress id="milk-progress" max="6" value="0" aria-label="Melkfortschritt"></progress></label><small>Sechs ruhige Melkbewegungen. Milch wird erst am Ende gutgeschrieben.</small><div class="work-buttons"><button id="milk-step">Melkbewegung</button><button id="milk-cancel">Abbrechen</button></div></div>';$('milk-step').onclick=()=>{if(done||!host.isConnected)return;count++;$('milk-progress').value=count;$('milk-percent').textContent=count+' / 6 · '+Math.round(count/6*100)+' %';if(count===6){done=true;commit();}};$('milk-cancel').onclick=()=>{done=true;animal(id,'Melken abgebrochen · keine Milch entnommen.');};host.scrollIntoView?.({block:'nearest',behavior:'smooth'});}else commit();};$('animal-housing').onclick=()=>{capture();const r=setHousing(s,id,!s.alpLife.housed[id]);if(r.ok)changed();animal(id,r.message);};$('farm-overview').onclick=()=>overview();
 }
 function supply(source,m=''){
  capture();const s=getState(),point=FARM_POINTS[source];show('<span class="eyebrow">GRUNDVERSORGUNG AUF DER ALP</span><h2>'+point.name+'</h2>'+message(m)+'<p>'+(source==='barn'?'Hier kannst du einen wiederverwendbaren Leiheimer holen. Dein Heu stammt von der Heuwiese. Körner für die Hühner erntest du am Kornfeld.':'Mit einem Eimer kannst du drei Portionen frisches Wasser abfüllen. Bis zu zwölf Portionen pro Spieltag stehen kostenlos bereit. Wasser ist für Tiere, Kochen und Trinken nutzbar.')+'</p><div class="care-status"><p>Im Rucksack: '+(s.inventory.hay||0)+' Heu · '+(s.inventory.grain||0)+' Körnerfutter · '+(s.inventory.water||0)+' Wasser · '+(s.inventory.bucket||0)+' Eimer</p></div>'+(source==='well'?'<button id="well-drink">Quellwasser trinken</button><button id="well-bottle">Trinkflasche auffüllen</button>':'')+'<button id="farm-supply-take" class="primary">'+(source==='barn'?'Leiheimer nehmen':'Wasser abfüllen')+'</button><p>Heu mähst du selbst; weitere Vorräte gibt es im Dorfladen.</p>');if(source==='well')for(const [id,action]of [['well-drink','drink'],['well-bottle','bottle']])$(id).onclick=()=>{capture();const r=farmSupply(s,action,exchangeInventory);if(r.ok)changed();supply(source,r.message);};$('farm-supply-take').onclick=()=>{capture();const result=farmSupply(s,source,exchangeInventory);if(result.ok)changed();supply(source,result.message);};
 }
 function overview(m=''){
  capture();const s=getState();show('<span class="eyebrow">LEBEN AUF DER PORTMANN-ALP</span><h2>Deine Tiere</h2>'+message(m)+'<p>Tag '+s.day+' · '+s.farm.completeDays+' vollständig versorgte Tage · '+s.farm.harvests+' Erzeugnisse abgeholt</p><div class="item-grid">'+Object.values(ANIMALS).map(a=>{const st=dailyStatus(s,a.id);return'<article class="item-card"><h3>'+a.name+'</h3>'+statusLine('Futter',st.fed)+statusLine('Wasser',st.watered)+statusLine('Pflege',st.cared)+'<button data-animal="'+a.id+'">Zustand ansehen</button></article>';}).join('')+'</div><button id="farm-housing-all">Alle Tiere in den Stall holen</button><button id="farm-release-all">Alle Tiere auf die Weide lassen</button><h3>Deine tägliche Runde</h3><p>Mähe Heu, hole Körner vom Kornfeld und Wasser am Brunnen. Abends bringst du die Tiere in die Scheune beziehungsweise ins Hühnerhaus; morgens lässt du sie wieder hinaus. Milch und Eier verarbeitest du in der Hütte.</p><p>Den Tageswechsel bestimmst du selbst durch Schlafen. Weitere Erzeugnisse bekommst du erst nach der Versorgung am nächsten Spieltag.</p>');for(const [button,inside] of [['farm-housing-all',true],['farm-release-all',false]])$(button).onclick=()=>{capture();let n=0,msg='Gehe zum Stalltor.';for(const id of Object.keys(ANIMALS)){const r=setHousing(s,id,inside);if(r.ok)n++;msg=r.message;}if(n)changed();overview(n?n+' Tiergruppen '+(inside?'auf dem Weg in den Stall.':'auf dem Weg zur Weide.'):msg);};for(const el of document.querySelectorAll('[data-animal]'))el.onclick=()=>animal(el.dataset.animal);
 }
 return{animal,supply,overview};
}
